    /** Styles for the floating watch area and the space it reserves in the sidebar. */
    const WATCHLIST_CSS = `
    /* The running mark's box and paint, duplicated out of tails.css so a slow or
       missing stylesheet still shows a resting tail instead of an empty gap. */
    .dshwl-whale{
      flex:none;display:inline-flex;
      width:calc(20px + var(--dsh-content-font-delta,0px));
      height:calc(20px + var(--dsh-content-font-delta,0px));
      color:var(--dsw-alias-state-business-primary,var(--dsw-static-deepseek-500));
    }
    /* Same colours the dots used: the tail inherits them through currentColor. */
    .dshwl-whale[data-status="unread"]{color:var(--dsw-alias-state-success-primary)}
    .dshwl-whale[data-status="waiting"]{color:var(--dsw-alias-state-warn-primary)}
    .dshwl-tail{display:block;width:100%;height:100%;overflow:visible}
    .dshwl-tail path{fill:currentColor;fill-rule:evenodd;stroke:none}
    [data-slot="sidebar.workspaces"]{
      display:flex!important;
      flex-direction:column;
      flex:1 1 auto;
      min-height:0;
      box-sizing:border-box;
      padding-top:var(--dsh-watchlist-reserve,0px);
      overflow:hidden;
    }
    [data-slot="sidebar.workspaces"]>*{flex:1 1 auto;min-height:0}
    .dshwl-panel{
      position:fixed;z-index:60;box-sizing:border-box;display:flex;flex-direction:column;
      padding:2px 12px 0 8px;margin:0;
      color:var(--dsw-alias-label-primary);
      font-size:14px;line-height:20px;font-weight:400;
      pointer-events:auto;overflow:hidden;
    }
    /* Header typography matches the sidebar's own section header ("工作区"). */
    .dshwl-head{
      display:flex;align-items:center;gap:6px;flex:none;height:32px;
      padding:0 0 0 4px;margin-bottom:4px;overflow:hidden;
    }
    .dshwl-head-title{
      flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
      color:var(--dsw-alias-label-tertiary, var(--dsw-alias-label-secondary));
      font-size:14px;line-height:20px;font-weight:400;
    }
    .dshwl-count{
      flex:none;color:var(--dsw-alias-label-tertiary, var(--dsw-alias-label-secondary));
      font-size:14px;line-height:20px;font-weight:400;opacity:.75;
    }
    .dshwl-list{display:flex;flex-direction:column;gap:1px;flex:0 1 auto;min-height:0;overflow-y:auto;overflow-x:hidden}
    .dshwl-row{
      display:flex;align-items:center;gap:8px;box-sizing:border-box;min-height:30px;width:100%;
      padding:5px 6px;border-radius:var(--dsw-radius-md,8px);cursor:pointer;text-align:left;
      color:var(--dsw-alias-label-primary);
      font-size:14px;line-height:20px;font-weight:400;
      background:transparent;white-space:nowrap;overflow:hidden;
    }
    .dshwl-row:hover,.dshwl-row[aria-current="page"]{background:var(--dsw-alias-bg-layer-2)}
    .dshwl-row:focus-visible{outline:var(--dsw-focus-ring-width,2px) solid var(--dsw-alias-state-business-primary,var(--dsw-static-deepseek-500));outline-offset:-2px}
    .dshwl-title{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis}
    .dshwl-mark{flex:none;width:20px;height:20px;display:inline-flex;align-items:center;justify-content:center}
    .dshwl-dot{flex:none;width:8px;height:8px;border-radius:50%;background:var(--dsw-alias-state-idle-primary);opacity:.45}
    .dshwl-dot[data-status="unread"]{background:var(--dsw-alias-state-success-primary);opacity:1}
    .dshwl-dot[data-status="waiting"]{background:var(--dsw-alias-state-warn-primary);opacity:1}
    .dshwl-dot[data-status="failed"]{background:var(--dsw-alias-state-error-primary);opacity:1}
    /* Row actions. The unwatch cross keeps its reserved slot so the title never
       shifts; the mark-unread action is display:none until the row is hovered or
       focused, so it adds nothing to the layout and nothing to the title's width
       while the row is idle. */
    .dshwl-unread,.dshwl-unfollow{
      flex:none;width:18px;height:18px;display:inline-flex;align-items:center;justify-content:center;
      padding:0;border:none;border-radius:var(--dsw-radius-sm,4px);background:transparent;
      color:var(--dsw-alias-label-secondary);cursor:pointer;
    }
    .dshwl-unfollow{opacity:0;transition:opacity .12s ease}
    .dshwl-row:hover .dshwl-unfollow,.dshwl-row:focus-within .dshwl-unfollow{opacity:1}
    .dshwl-unread{display:none}
    .dshwl-row:hover .dshwl-unread,.dshwl-row:focus-within .dshwl-unread{display:inline-flex}
    .dshwl-unread:hover,.dshwl-unfollow:hover{background:var(--dsw-alias-bg-base);color:var(--dsw-alias-label-primary)}
    .dshwl-unread-mark{
      box-sizing:border-box;width:9px;height:9px;border-radius:50%;
      border:1.4px solid currentColor;transition:background .12s ease,border-color .12s ease;
    }
    .dshwl-unread[data-active="true"] .dshwl-unread-mark{
      background:var(--dsw-alias-state-success-primary);
      border-color:var(--dsw-alias-state-success-primary);
    }
    .dshwl-empty{
      padding:0 4px 2px;
      color:var(--dsw-alias-label-tertiary, var(--dsw-alias-label-secondary));
      font-size:14px;line-height:20px;font-weight:400;
      white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
    }
    `

